import re
from moler.device.device import DeviceFactory
from moler.util.moler_test import MolerTest
from taf.ul.sc.util.helpers import is_dry_run


class GenericFunctionality(object):
    """
    Generic class for other device connections.
    """
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def __init__(self, device_name=None, device=None, autoconnect=False, get_device=False):
        """

        :param device_name:
        :param autoconnect: True or False - automatic connect to device after instance of class is created
        :param get_device: Get instance of device from moler configuration
        :param device: Moler device
        """
        self.device = None

        if device:
            self.device = device
            self.name = self.device.name
        elif device_name:
            self.name = str(device_name)
        else:
            raise Exception("One of parameters: 'device_name' or 'device' should be passed")

        self.ws_name = self._build_ws_device_name()
        self.number = self._get_device_number()

        if get_device and not device:
            self.device = DeviceFactory.get_device(name=self.name, establish_connection=False)
        if autoconnect and not is_dry_run():
            self.connect()

    @MolerTest.raise_background_exceptions(check_steps_end=True)
    def connect(self):
        """
        The keyword creates device object based on the given device name.
        :return: nothing
        """
        if not self.device:
            self.device = DeviceFactory.get_device(name=self.name)
        self.device.goto_state(state=self.device.initial_state)

        MolerTest.steps_end()

    def reconnect(self, initial_state):
        self.device.goto_state(initial_state)

    def _build_ws_device_name(self):
        """
        Build workstation name for the device.

        :return: workstation name
        """
        return "{}_WS".format(self.name)

    def _get_device_number(self):
        """
        Get device number
        :return: device_number or None
        """
        match = re.search(r"^[^\W_\d]+(?P<DEVICE_NUMBER>\d+)", self.name)
        return match.group('DEVICE_NUMBER') if match else None
